INSERT INTO `config_info` VALUES (353, 'project-commodity.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.system-master.url}\n          username: ${datasource.system-master.username}\n          password: ${datasource.system-master.password}\n        # 从库数据源\n        # slave:\n        #  driver-class-name:\n        #  url:\n        #  username:\n        #  password:', 'af3ac88616679145a719da60494efc60', '2022-06-10 15:34:04', '2022-06-10 15:35:31', 'nacos', '192.168.0.105', '', 'dev', '商品订单模块', '', '', 'yaml', '', NULL);
