INSERT INTO `his_config_info` VALUES (0, 80, 'com.project.resource.api.RemoteFileService:::provider:project-resource', 'DUBBO_GROUP', '', '{\"parameters\":{\"side\":\"provider\",\"interface\":\"com.project.resource.api.RemoteFileService\",\"pid\":\"20672\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"dubbo\":\"2.0.2\",\"release\":\"3.0.8\",\"anyhost\":\"true\",\"methods\":\"upload\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"qos.enable\":\"false\",\"generic\":\"false\",\"bind.port\":\"20880\",\"bind.ip\":\"192.168.0.105\",\"background\":\"false\",\"dynamic\":\"true\",\"timestamp\":\"1654085271895\"},\"canonicalName\":\"com.project.resource.api.RemoteFileService\",\"codeSource\":\"file:/E:/ProgramData/RuoYi-Cloud-Plus/project-api/project-api-resource/target/classes/\",\"methods\":[{\"name\":\"upload\",\"parameterTypes\":[\"java.lang.String\",\"java.lang.String\",\"java.lang.String\",\"byte[]\"],\"returnType\":\"com.project.resource.api.domain.SysFile\",\"annotations\":[]}],\"types\":[{\"type\":\"byte[]\",\"items\":[\"byte\"]},{\"type\":\"byte\"},{\"type\":\"com.project.resource.api.domain.SysFile\",\"properties\":{\"name\":\"java.lang.String\",\"url\":\"java.lang.String\"}},{\"type\":\"java.lang.String\"}],\"annotations\":[]}', '90502316006b75557f151bdb3edb701a', '2022-06-01 20:07:52', '2022-06-01 12:07:52', NULL, '192.168.0.105', 'I', '', NULL);
