INSERT INTO `his_config_info` VALUES (0, 82, 'com.project.resource.api.RemoteSmsService:::provider:project-resource', 'DUBBO_GROUP', '', '{\"parameters\":{\"side\":\"provider\",\"interface\":\"com.project.resource.api.RemoteSmsService\",\"pid\":\"20672\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"dubbo\":\"2.0.2\",\"release\":\"3.0.8\",\"anyhost\":\"true\",\"methods\":\"send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"qos.enable\":\"false\",\"generic\":\"false\",\"bind.port\":\"20880\",\"bind.ip\":\"192.168.0.105\",\"background\":\"false\",\"dynamic\":\"true\",\"timestamp\":\"1654085272249\"},\"canonicalName\":\"com.project.resource.api.RemoteSmsService\",\"codeSource\":\"file:/E:/ProgramData/RuoYi-Cloud-Plus/project-api/project-api-resource/target/classes/\",\"methods\":[{\"name\":\"send\",\"parameterTypes\":[\"java.lang.String\",\"java.lang.String\",\"java.util.Map\\u003cjava.lang.String,java.lang.String\\u003e\"],\"returnType\":\"com.project.resource.api.domain.SysSms\",\"annotations\":[]}],\"types\":[{\"type\":\"com.project.resource.api.domain.SysSms\",\"properties\":{\"response\":\"java.lang.Object\",\"message\":\"java.lang.String\",\"isSuccess\":\"java.lang.Boolean\"}},{\"type\":\"java.lang.Boolean\"},{\"type\":\"java.lang.Object\"},{\"type\":\"java.lang.String\"},{\"type\":\"java.util.Map\\u003cjava.lang.String,java.lang.String\\u003e\",\"items\":[\"java.lang.String\",\"java.lang.String\"]}],\"annotations\":[]}', '0dc40041af7d8109bcdff4da7224afa2', '2022-06-01 20:07:52', '2022-06-01 12:07:52', NULL, '192.168.0.105', 'I', '', NULL);
