ruoyi-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.ruoyi.system.api.RemoteDataScopeService:dubbo\":{\"name\":\"com.ruoyi.system.api.RemoteDataScopeService\",\"protocol\":\"dubbo\",\"path\":\"com.ruoyi.system.api.RemoteDataScopeService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getDeptAndChild,getRoleCustom\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.ruoyi.system.api.RemoteDataScopeService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"ruoyi-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}}}}', 'f6cabd156273a818bb2fcc788e516871', '2022-06-01 20:22:36', '2022-06-01 12:22:37', NULL, '192.168.0.105', 'U', '', NULL);
INSERT INTO `his_config_info` VALUES (132, 126, 'com.ruoyi.system.api.RemoteUserService:::provider:ruoyi-system', 'DUBBO_GROUP', '', '{\"parameters\":{\"side\":\"provider\",\"interface\":\"com.ruoyi.system.api.RemoteUserService\",\"pid\":\"21096\",\"metadata-type\":\"remote\",\"application\":\"ruoyi-system\",\"dubbo\":\"2.0.2\",\"release\":\"3.0.8\",\"anyhost\":\"true\",\"methods\":\"getUserInfoByPhonenumber,registerUserInfo,getUserInfoByOpenid,getUserInfo\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"qos.enable\":\"false\",\"generic\":\"false\",\"bind.port\":\"20881\",\"bind.ip\":\"192.168.0.105\",\"background\":\"false\",\"dynamic\":\"true\",\"timestamp\":\"1653994553408\"},\"canonicalName\":\"com.ruoyi.system.api.RemoteUserService\",\"codeSource\":\"file:/G:/RuoYi/RuoYi-Cloud-Plus/ruoyi-api/ruoyi-api-system/target/classes/\",\"methods\":[{\"name\":\"getUserInfoByPhonenumber\",\"parameterTypes\":[\"java.lang.String\"],\"returnType\":\"com.ruoyi.system.api.model.LoginUser\",\"annotations\":[]},{\"name\":\"getUserInfoByOpenid\",\"parameterTypes\":[\"java.lang.String\"],\"returnType\":\"com.ruoyi.system.api.model.XcxLoginUser\",\"annotations\":[]},{\"name\":\"registerUserInfo\",\"parameterTypes\":[\"com.ruoyi.system.api.domain.SysUser\"],\"returnType\":\"java.lang.Boolean\",\"annotations\":[]},{\"name\":\"getUserInfo\",\"parameterTypes\":[\"java.lang.String\"],\"returnType\":\"com.ruoyi.system.api.model.LoginUser\",\"annotations\":[]}],\"types\":[{\"type\":\"java.util.List\\u003cT\\u003e\"},{\"type\":\"com.ruoyi.system.api.domain.SysRole\",\"properties\":{\"flag\":\"boolean\",\"roleId\":\"java.lang.Long\",\"remark\":\"java.lang.String\",\"updateTime\":\"java.util.Date\",\"dataScope\":\"java.lang.String\",\"delFlag\":\"java.lang.String\",\"params\":\"java.util.Map\\u003cjava.lang.String,java.lang.Object\\u003e\",\"roleSort\":\"java.lang.Integer\",\"deptCheckStrictly\":\"java.lang.Boolean\",\"createBy