INSERT INTO `his_config_info` VALUES (184, 210, 'project-system', '38b21085af46b1a98590cc5c161150e4', '', '{\"app\":\"project-system\",\"revision\":\"38b21085af46b1a98590cc5c161150e4\",\"services\":{\"com.project.system.api.RemoteLogService:dubbo\":{\"name\":\"com.project.system.api.RemoteLogService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteLogService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"saveLog,saveLogininfor\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteLogService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteDictService:dubbo\":{\"name\":\"com.project.system.api.RemoteDictService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteDictService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getDictLabel,getDictValue\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteDictService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteDataScopeService:dubbo\":{\"name\":\"com.project.system.api.RemoteDataScopeService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteDataScopeService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getDeptAndChild,getRoleCustom\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteDataScopeService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteUserService:dubbo\":{\"name\":\"com.project.system.api.RemoteUserService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteUserService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getUserInfoByPhonenumber,registerUserInfo,getUserInfoByOpenid,getUserInfo\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteUserService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}}}}', 'fea0a4a7a64e96e70175fdc980b332a3', '2022-06-06 07:14:02', '2022-06-05 23:14:02', NULL, '192.168.0.105', 'D', '', NULL);
INSERT INTO `his_config_info` VALUES (3, 211, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    # 是否开启验证码\n    enabled: true\n    # 验证码类型 math 数组计算 char 字符验证\n    type: MATH\n    # line 线段干扰 circle 圆圈干扰 shear 扭曲干扰\n    category: CIRCLE\n    # 数字验证码位数\n    numberLength: 1\n    # 字符验证码长度\n    charLength: 4\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /code\n      - /auth/logout\n      - /auth/login\n      - /auth/smsLogin\n      - /auth/xcxLogin\n      - /auth/register\n      - /resource/sms/code\n      - /*/v2/api-docs\n      - /csrf\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: ruoyi-auth\n          uri: lb://ruoyi-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: ruoyi-gen\n          uri: lb://ruoyi-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: ruoyi-system\n          uri: lb://ruoyi-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 资源服务\n        - id: ruoyi-resource\n          uri: lb://ruoyi-resource\n          predicates:\n            - Path=/resource/**\n          filters:\n            - StripPrefix=1\n\n    # sentinel 配置\n    sentinel:\n      # nacos配置持久化\n      datasource:\n        ds1:\n          nacos:\n            server-addr: ${spring.cloud.nacos.server-addr}\n            dataId: sentinel-${spring.application.name}.json\n            groupId: ${spring.cloud.nacos.config.group}\n            namespace: ${spring.profiles.active}\n            data-type: json\n            rule-type: flow\n', '5463aa964faba886f9b6edcb3b7ad974', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (4, 212, 'ruoyi-auth.yml', 'DEFAULT_GROUP', '', '# 将项目路径：config/下对应文件中内容复制到此处', '2944a25cb97926efcaa43b3ad7a64cf0', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (5, 213, 'ruoyi-monitor.yml', 'DEFAULT_GROUP', '', '# 监控中心配置\nspring:\n  security:\n    user:\n      name: ruoyi\n      password: 123456\n  boot:\n    admin:\n      ui:\n        title: RuoYi-Cloud-Plus服务监控中心\n      discovery:\n        # seata 不具有健康检查的能力 防止报错排除掉\n        ignored-services: seata-server\n', '13ebad4eae8c5974d9d5cfda4f944dbc', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (6, 214, 'ruoyi-system.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.system-master.url}\n          username: ${datasource.system-master.username}\n          password: ${datasource.system-master.password}\n        # 从库数据源\n        # slave:\n        #  driver-class-name:\n        #  url:\n        #  username:\n        #  password:\n', '568773caedfdb639db5fd807aad3993d', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (7, 215, 'ruoyi-gen.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.system-master.url}\n          username: ${datasource.system-master.username}\n          password: ${datasource.system-master.password}\n        # 从库数据源\n        #slave:\n        #  lazy: true\n        #  driver-class-name:\n        #  url:\n        #  username:\n        #  password:\n\n# 代码生成\ngen:\n  # 作者\n  author: ruoyi\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\n  packageName: com.ruoyi.system\n  # 自动去除表前缀，默认是false\n  autoRemovePre: false\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\n  tablePrefix: sys_\n', '4a910788dcd9e831f5bde9b6f389d36e', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (8, 216, 'ruoyi-job.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.job.url}\n          username: ${datasource.job.username}\n          password: ${datasource.job.password}\n\nxxl:\n  job:\n    # 执行器开关\n    enabled: true\n    # 调度中心地址：如调度中心集群部署存在多个地址则用逗号分隔。\n    admin-addresses: http://127.0.0.1:9900\n    # 执行器通讯TOKEN：非空时启用\n    access-token: xxl-job\n    # 执行器配置\n    executor:\n      # 执行器AppName：执行器心跳注册分组依据；为空则关闭自动注册\n      appname: ${spring.application.name}-executor\n      # 执行器端口号 执行器从19901开始往后写\n      port: 9901\n      # 执行器注册：默认IP:PORT\n      address:\n      # 执行器IP：默认自动获取IP\n      ip:\n      # 执行器运行日志文件存储磁盘路径\n      logpath: ./logs/${spring.application.name}/xxl-job\n      # 执行器日志文件保存天数：大于3生效\n      logretentiondays: 30\n', 'b45ac3d15c1ed59707c6e241adb22432', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (9, 217, 'ruoyi-resource.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.system-master.url}\n          username: ${datasource.system-master.username}\n          password: ${datasource.system-master.password}\n        # 从库数据源\n        # slave:\n        #  driver-class-name:\n        #  url:\n        #  username:\n        #  password:\n\nmail:\n  enabled: false\n  host: smtp.163.com\n  port: 465\n  # 是否需要用户名密码验证\n  auth: true\n  # 发送方，遵循RFC-822标准\n  from: xxx@163.com\n  # 用户名（注意：如果使用foxmail邮箱，此处user为qq号）\n  user: xxx@163.com\n  # 密码（注意，某些邮箱需要为SMTP服务单独设置密码，详情查看相关帮助）\n  pass: xxxxxxxxxx\n  # 使用 STARTTLS安全连接，STARTTLS是对纯文本通信协议的扩展。\n  starttlsEnable: true\n  # 使用SSL安全连接\n  sslEnable: true\n  # SMTP超时时长，单位毫秒，缺省值不超时\n  timeout: 0\n  # Socket连接超时值，单位毫秒，缺省值不超时\n  connectionTimeout: 0\n\nsms:\n  enabled: false\n  # 阿里云 dysmsapi.aliyuncs.com\n  # 腾讯云 sms.tencentcloudapi.com\n  endpoint: \"dysmsapi.aliyuncs.com\"\n  accessKeyId: xxxxxxx\n  accessKeySecret: xxxxxx\n  signName: 测试\n  # 腾讯专用\n  sdkAppId:\n', '9356ff04b686a3cc692059758424e14e', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (10, 218, 'sentinel-ruoyi-gateway.json', 'DEFAULT_GROUP', '', '[\n  {\n    \"resource\": \"ruoyi-auth\",\n    \"count\": 500,\n    \"grade\": 1,\n    \"limitApp\": \"default\",\n    \"strategy\": 0,\n    \"controlBehavior\": 0\n  },\n  {\n    \"resource\": \"ruoyi-system\",\n    \"count\": 1000,\n    \"grade\": 1,\n    \"limitApp\": \"default\",\n    \"strategy\": 0,\n    \"controlBehavior\": 0\n  },\n  {\n    \"resource\": \"ruoyi-resource\",\n    \"count\": 500,\n    \"grade\": 1,\n    \"limitApp\": \"default\",\n    \"strategy\": 0,\n    \"controlBehavior\": 0\n  }\n]\n', '2efad3702e99adef46c2ee818b3925e5', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (11, 219, 'ruoyi-xxl-job-admin.yml', 'DEFAULT_GROUP', '', '# server 配置\nspring:\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: ${datasource.job.url}\n    username: ${datasource.job.username}\n    password: ${datasource.job.password}\n    hikari:\n      auto-commit: true\n      connection-test-query: SELECT 1\n      connection-timeout: 10000\n      idle-timeout: 30000\n      max-lifetime: 900000\n      maximum-pool-size: 30\n      minimum-idle: 10\n      pool-name: HikariCP\n      validation-timeout: 1000\n  mail:\n    from: xxx@qq.com\n    host: smtp.qq.com\n    username: xxx@qq.com\n    password: xxx\n    port: 25\n    properties:\n      mail:\n        smtp:\n          auth: true\n          socketFactory:\n            class: javax.net.ssl.SSLSocketFactory\n          starttls:\n            enable: true\n            required: true\n\n# mybatis 配置\nmybatis:\n  mapper-locations: classpath:/mybatis-mapper/*Mapper.xml\n\n# Actuator 监控端点的配置项\nmanagement:\n  health:\n    mail:\n      enabled: false\n\n# xxljob系统配置\nxxl:\n  job:\n    # 鉴权token\n    accessToken: xxl-job\n    # 国际化\n    i18n: zh_CN\n    # 日志清理\n    logretentiondays: 30\n    triggerpool:\n      fast:\n        max: 200\n      slow:\n        max: 100\n', '71f881b9b27d4be062971515f6fbbeb3', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (13, 220, 'ruoyi-sentinel-dashboard.yml', 'DEFAULT_GROUP', '', 'server:\n  servlet:\n    encoding:\n      force: true\n      charset: UTF-8\n      enabled: true\n    session:\n      cookie:\n        name: sentinel_dashboard_cookie\n\nlogging:\n  level:\n    org.springframework.web: INFO\n\nauth:\n  enabled: true\n  filter:\n    exclude-urls: /,/auth/login,/auth/logout,/registry/machine,/version\n    exclude-url-suffixes: htm,html,js,css,map,ico,ttf,woff,png\n  username: sentinel\n  password: sentinel\n', '071d0afa06606f4522e94ce53caf6595', '2022-06-06 07:14:27', '2022-06-05 23:14:28', NULL, '192.168.0.105', 'D', 'dev', NULL);
INSERT INTO `his_config_info` VALUES (12, 221, 'seata-server.properties', 'DEFAULT_GROUP', '', 'service.vgroupMapping.project-auth-group=default\nservice.vgroupMapping.project-system-group=default\nservice.vgroupMapping.project-resource-group=default\nservice.vgroupMapping.project-gen-group=default\nservice.vgroupMapping.project-job-group=default\nservice.enableDegrade=false\nservice.disableGlobalTransaction=false\nstore.mode=db\nstore.publicKey=\nstore.db.datasource=druid\nstore.db.dbType=mysql\nstore.db.driverClassName=com.mysql.cj.jdbc.Driver\nstore.db.url=jdbc:mysql://127.0.0.1:3306/ry-seata?useUnicode=true&rewriteBatchedStatements=true\nstore.db.user=root\nstore.db.password=password\nstore.db.minConn=5\nstore.db.maxConn=30\nstore.db.globalTable=global_table\nstore.db.branchTable=branch_table\nstore.db.distributedLockTable=distributed_lock\nstore.db.queryLimit=100\nstore.db.lockTable=lock_table\nstore.db.maxWait=5000\nserver.recovery.committingRetryPeriod=1000\nserver.recovery.asynCommittingRetryPeriod=1000\nserver.recovery.rollbackingRetryPeriod=1000\nserver.recovery.timeoutRetryPeriod=1000\nserver.maxCommitRetryTimeout=-1\nserver.maxRollbackRetryTimeout=-1\nserver.rollbackRetryTimeoutUnlockEnable=false\nserver.distributedLockExpireTime=10000\nclient.undo.dataValidation=true\nclient.undo.logSerialization=kryo\nclient.undo.onlyCareUpdateColumns=true\nserver.undo.logSaveDays=7\nserver.undo.logDeletePeriod=86400000\nclient.undo.logTable=undo_log\nclient.undo.compress.enable=true\nclient.undo.compress.type=zip\nclient.undo.compress.threshold=64k\nlog.exceptionRate=100\ntransport.serialization=seata\ntransport.compressor=none\nmetrics.enabled=false\nmetrics.registryType=compact\nmetrics.exporterList=prometheus\nmetrics.exporterPrometheusPort=9898\ntcc.fence.logTableName=tcc_fence_log\ntcc.fence.cleanPeriod=1h\n', 'e34bb7c72f9031c817f7f2ce7b75e63f', '2022-06-06 07:16:05', '2022-06-05 23:16:06', 'nacos', '192.168.0.105', 'U', 'dev', NULL);
