INSERT INTO `his_config_info` VALUES (251, 453, 'project-system', '38b21085af46b1a98590cc5c161150e4', '', '{\"app\":\"project-system\",\"revision\":\"38b21085af46b1a98590cc5c161150e4\",\"services\":{\"com.project.system.api.RemoteLogService:dubbo\":{\"name\":\"com.project.system.api.RemoteLogService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteLogService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"saveLog,saveLogininfor\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteLogService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteDictService:dubbo\":{\"name\":\"com.project.system.api.RemoteDictService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteDictService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getDictLabel,getDictValue\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteDictService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteDataScopeService:dubbo\":{\"name\":\"com.project.system.api.RemoteDataScopeService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteDataScopeService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getDeptAndChild,getRoleCustom\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteDataScopeService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.system.api.RemoteUserService:dubbo\":{\"name\":\"com.project.system.api.RemoteUserService\",\"protocol\":\"dubbo\",\"path\":\"com.project.system.api.RemoteUserService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"getUserInfoByPhonenumber,registerUserInfo,getUserInfoByOpenid,getUserInfo\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.system.api.RemoteUserService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-system\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}}}}', 'fea0a4a7a64e96e70175fdc980b332a3', '2022-06-10 19:51:49', '2022-06-10 11:51:49', NULL, '192.168.0.105', 'U', '', NULL);
