INSERT INTO `his_config_info` VALUES (242, 471, 'project-resource', '5554d86e101d0bd0f399433737a1f4b9', '', '{\"app\":\"project-resource\",\"revision\":\"5554d86e101d0bd0f399433737a1f4b9\",\"services\":{\"com.project.resource.api.RemoteMailService:dubbo\":{\"name\":\"com.project.resource.api.RemoteMailService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteMailService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"sendWithAttachment,send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteMailService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.resource.api.RemoteFileService:dubbo\":{\"name\":\"com.project.resource.api.RemoteFileService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteFileService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"upload\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteFileService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.resource.api.RemoteSmsService:dubbo\":{\"name\":\"com.project.resource.api.RemoteSmsService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteSmsService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteSmsService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"ba