INSERT INTO `his_config_info` VALUES (242, 481, 'project-resource', '5554d86e101d0bd0f399433737a1f4b9', '', '{\"app\":\"project-resource\",\"revision\":\"5554d86e101d0bd0f399433737a1f4b9\",\"services\":{\"com.project.resource.api.RemoteMailService:dubbo\":{\"name\":\"com.project.resource.api.RemoteMailService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteMailService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"sendWithAttachment,send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteMailService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.resource.api.RemoteFileService:dubbo\":{\"name\":\"com.project.resource.api.RemoteFileService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteFileService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"upload\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteFileService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}},\"com.project.resource.api.RemoteSmsService:dubbo\":{\"name\":\"com.project.resource.api.RemoteSmsService\",\"protocol\":\"dubbo\",\"path\":\"com.project.resource.api.RemoteSmsService\",\"params\":{\"side\":\"provider\",\"release\":\"3.0.8\",\"methods\":\"send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"dubbo\":\"2.0.2\",\"interface\":\"com.project.resource.api.RemoteSmsService\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"generic\":\"false\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"background\":\"false\",\"dynamic\":\"true\",\"anyhost\":\"true\"}}}}', '9396eee028ab5598954a35fd7d8619be', '2022-06-10 20:45:27', '2022-06-10 12:45:28', NULL, '192.168.0.105', 'U', '', NULL);
INSERT INTO `his_config_info` VALUES (239, 482, 'com.project.resource.api.RemoteSmsService:::provider:project-resource', 'DUBBO_GROUP', '', '{\"parameters\":{\"side\":\"provider\",\"interface\":\"com.project.resource.api.RemoteSmsService\",\"pid\":\"5744\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"dubbo\":\"2.0.2\",\"release\":\"3.0.8\",\"anyhost\":\"true\",\"methods\":\"send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"qos.enable\":\"false\",\"generic\":\"false\",\"bind.port\":\"20880\",\"bind.ip\":\"192.168.0.105\",\"background\":\"false\",\"dynamic\":\"true\",\"timestamp\":\"1654864553302\"},\"canonicalName\":\"com.project.resource.api.RemoteSmsService\",\"codeSource\":\"file:/E:/ProgramData/RuoYi-Cloud-Plus/project-api/project-api-resource/target/classes/\",\"methods\":[{\"name\":\"send\",\"parameterTypes\":[\"java.lang.String\",\"java.lang.String\",\"java.util.Map\\u003cjava.lang.String,java.lang.String\\u003e\"],\"returnType\":\"com.project.resource.api.domain.SysSms\",\"annotations\":[]}],\"types\":[{\"type\":\"com.project.resource.api.domain.SysSms\",\"properties\":{\"response\":\"java.lang.Object\",\"message\":\"java.lang.String\",\"isSuccess\":\"java.lang.Boolean\"}},{\"type\":\"java.lang.Boolean\"},{\"type\":\"java.lang.Object\"},{\"type\":\"java.lang.String\"},{\"type\":\"java.util.Map\\u003cjava.lang.String,java.lang.String\\u003e\",\"items\":[\"java.lang.String\",\"java.lang.String\"]}],\"annotations\":[]}', '87e8854633b2b7a02850ed6b9e7fb493', '2022-06-10 20:45:27', '2022-06-10 12:45:28', NULL, '192.168.0.105', 'U', '', NULL);
INSERT INTO `his_config_info` VALUES (241, 483, 'com.project.resource.api.RemoteMailService:::provider:project-resource', 'DUBBO_GROUP', '', '{\"parameters\":{\"side\":\"provider\",\"interface\":\"com.project.resource.api.RemoteMailService\",\"pid\":\"5744\",\"metadata-type\":\"remote\",\"application\":\"project-resource\",\"dubbo\":\"2.0.2\",\"release\":\"3.0.8\",\"anyhost\":\"true\",\"methods\":\"sendWithAttachment,send\",\"logger\":\"slf4j\",\"deprecated\":\"false\",\"service-name-mapping\":\"true\",\"register-mode\":\"instance\",\"qos.enable\":\"false\",\"generic\":\"false\",\"bind.port\":\"20880\",\"bind.ip\":\"192.168.0.105\",\"background\":\"false\",\"dynamic\":\"true\",\"timestamp\":\"1654864553316\"},\"canonicalName\":\"com.project.resource.api.RemoteMailService\",\"codeSource\":\"file:/E:/ProgramData/RuoYi-Cloud-Plus/project-api/project-api-resource/target/classes/\",\"methods\":[{\"name\":\"send\",\"parameterTypes\":[\"java.lang.String\",\"java.lang.String\",\"java.lang.String\"],\"returnType\":\"void\",\"annotations\":[]},{\"name\":\"sendWithAttachment\",\"parameterTypes\":[\"java.lang.String\",\"java.lang.String\",\"java.lang.String\",\"java.util.List\\u003cjava.io.File\\u003e\"],\"returnType\":\"void\",\"annotations\":[]}],\"types\":[{\"type\":\"void\"},{\"type\":\"java.lang.String\"},{\"type\":\"java.io.File\",\"properties\":{\"path\":\"java.lang.String\"}},{\"type\":\"java.util.List\\u003cjava.io.File\\u003e\",\"items\":[\"java.io.File\"]}],\"annotations\":[]}', 'c4346bf916f170853f4787b23f0d2fa7', '2022-06-10 20:45:27', '2022-06-10 12:45:28', NULL, '192.168.0.105', 'U', '', NULL);
